{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C03","C15","C17","C13","C21","C31","C06","C08","C32","C90","C131","C97"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03","C15","C13","C06","C08","C90","C131"],
  "claims": [
    {
      "claim": "In patients with cirrhosis, bumetanide—a loop diuretic with acidic ionizable groups—had absolute oral bioavailability of 0.95 after 1 mg oral vs IV, also reported as 95%; L2 reports 95–100%.",
      "card_ids": ["C03","C15","C17"]
    },
    {
      "claim": "In patients with alcoholic cirrhosis, tolfenamic acid had absolute oral bioavailability of about 100% after 100 mg p.o. vs i.v.; L2 reports a mean of 113 ± 11%.",
      "card_ids": ["C13","C21","C31"]
    },
    {
      "claim": "In patients with cirrhosis, isradipine had mean systemic availability of 36.9–37% (L2 also reports 41%), all above the 20% threshold.",
      "card_ids": ["C06","C08","C32"]
    },
    {
      "claim": "L4 shows glipizide, a sulfonylurea, is >95% absorbed in humans and has high Caco-2 permeability (19 × 10^-6 cm/s) despite low intrinsic solubility (1.4 µg/mL), supporting that ionized/polar sulfonylureas can be well absorbed.",
      "card_ids": ["C90","C131","C97"]
    },
    {
      "claim": "L4 gliclazide and tolbutamide solubility records are low but do not establish F < 20%; they are not affirmative threshold-relevant negative evidence for the query.",
      "card_ids": ["C108","C103","C89"]
    },
    {
      "claim": "The query is a pyridine-sulfonylurea loop diuretic; the closest cirrhosis-context analog bumetanide and related sulfonylurea absorption evidence support F >= 20%.",
      "card_ids": ["C03","C15","C90","C131"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C90","C131","C97","C108","C103","C89"]
    }
  ],
  "evidence_gaps": [
    "No direct torasemide bioavailability, absorption, solubility, or permeability record is supplied; all L4 records are for other molecules.",
    "Cirrhosis severity, portal shunting, formulation, and dose for the query are unspecified.",
    "The physicochemical prior is computed only and does not account for possible transporter-mediated absorption.",
    "L3 oral exposure records lack IV comparators and cannot provide absolute F for the query.",
    "Transfer from bumetanide/tolfenamic acid/isradipine and sulfonylurea absorption records is indirect."
  ],
  "decision_summary": "L4 adds supportive but indirect absorption evidence: glipizide, a sulfonylurea, is >95% absorbed with high Caco-2 permeability despite low intrinsic solubility, and gliclazide/tolbutamide low-solubility records do not demonstrate F<20%. Combined with high-F cirrhosis-context analogs (bumetanide 95%, tolfenamic acid ~100%, isradipine 37%), F>=20% remains better supported. Prediction: high; confidence moderate."
}

